// Reader RW5b: the TypeScript evaluator on RW5b's panels corpus (spec §8.7; G21, G22, G46).
//
// figurePanelsCorpus.json is generated by tests/figure_panels_corpus.py and run
// by tests/test_figure_panels.py too. Every panel's data agrees within 1e-9
// relative; a case marked `exact` (arithmetic only) agrees EXACTLY, so its RK4
// trajectory or iterated map is identical step for step. The rejected specs
// are refused by both compilers, and the caps are the Python twin's.
import { describe, expect, it } from "vitest";
import corpus from "./figurePanelsCorpus.json";
import {
  ADVANCED_KINDS,
  DEFAULT_FIELD_CELLS,
  DEFAULT_HEATMAP_CELLS,
  DEFAULT_ITERATIONS,
  DEFAULT_TRAJECTORY_STEPS,
  ESCAPE_MARGIN,
  MAX_CONTOURS,
  MAX_FIELD_CELLS,
  MAX_HEATMAP_CELLS,
  MAX_ITERATIONS,
  MAX_PANEL_WORK,
  MAX_TRAJECTORY_STEPS,
  advancedKinds,
  compileSpec,
  evaluateFigure,
  type FigureSpec,
} from "./figureSpec";

function close(actual: number | null, expected: number | null, tolerance: number): boolean {
  if (expected === null) return actual === null;
  if (actual === null) return false;
  return Math.abs(actual - expected) <= tolerance * Math.max(1, Math.abs(actual), Math.abs(expected));
}

/** Every number in two outputs agrees (structure exactly); tolerance 0 is exact equality. */
function sameData(actual: unknown, expected: unknown, tolerance: number, path = "$"): void {
  if (typeof expected === "number" || expected === null) {
    const ok = tolerance === 0 ? actual === expected : close(actual as number | null, expected as number | null, tolerance);
    if (!ok) throw new Error(`${path}: ${String(actual)} != ${String(expected)}`);
    return;
  }
  if (Array.isArray(expected)) {
    expect(Array.isArray(actual), path).toBe(true);
    expect((actual as unknown[]).length, path).toBe(expected.length);
    expected.forEach((item, index) => sameData((actual as unknown[])[index], item, tolerance, `${path}[${index}]`));
    return;
  }
  if (typeof expected === "object") {
    expect(Object.keys(actual as object).sort(), path).toEqual(Object.keys(expected as object).sort());
    for (const [key, item] of Object.entries(expected as object)) sameData((actual as Record<string, unknown>)[key], item, tolerance, `${path}.${key}`);
    return;
  }
  expect(actual, path).toEqual(expected);
}

describe("RW5b panels corpus", () => {
  it("pins the Python twin's caps", () => {
    expect(corpus.caps).toEqual({
      MAX_HEATMAP_CELLS, DEFAULT_HEATMAP_CELLS, MAX_FIELD_CELLS, DEFAULT_FIELD_CELLS, MAX_TRAJECTORY_STEPS,
      DEFAULT_TRAJECTORY_STEPS, MAX_ITERATIONS, DEFAULT_ITERATIONS, MAX_CONTOURS, MAX_PANEL_WORK, ESCAPE_MARGIN,
    });
  });

  it("covers every RW5b panel kind, the overlay, the time variable and every way a path stops", () => {
    const kinds = new Set(corpus.figures.flatMap((item) => advancedKinds(item.spec as unknown as FigureSpec)));
    expect([...kinds].sort()).toEqual([...ADVANCED_KINDS].sort());
    const stops = new Set(corpus.figures.flatMap((item) => item.expected.flatMap((data) => data.panels.map((panel) => (panel as { stopped?: string | null }).stopped ?? "none"))));
    for (const stop of ["none", "left_plot", "not_finite", "starts_outside"]) expect(stops.has(stop), stop).toBe(true);
    expect(corpus.figures.some((item) => item.exact && item.spec.panels.some((panel) => panel.kind === "trajectory_2d"))).toBe(true);
  });

  for (const item of corpus.figures) {
    it(`${item.id}${item.exact ? " (exact, step for step)" : ""}`, () => {
      const compiled = compileSpec(item.spec as unknown as FigureSpec);
      item.params.forEach((params, index) => {
        sameData(evaluateFigure(compiled, params as Record<string, number>), item.expected[index], item.exact ? 0 : corpus.tolerance.relative);
      });
    });
  }

  for (const item of corpus.rejected_figures) {
    it(`rejects ${item.id}`, () => {
      expect(() => compileSpec(item.spec as unknown as FigureSpec)).toThrow();
    });
  }
});
